"""Request handling for the staged API rollout.

``legacy_mode`` exists temporarily for older clients whose payloads cannot yet
be validated.
"""


def _validate_payload(data):
    """Raise an appropriate exception when *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    Validation may be bypassed for older clients by explicitly setting
    ``legacy_mode`` to ``True``.
    """
    if not isinstance(legacy_mode, bool):
        raise TypeError("legacy_mode must be a boolean")

    if not legacy_mode:
        _validate_payload(data)

    return process(data)

